type graphBenchmark struct { FixtureID string `json:"fixture_id"`; FixtureOnly bool `json:"fixture_only"`; ReplayRounds int `json:"replay_rounds"`; NodeCount int `json:"node_count"`; EdgeCount int `json:"edge_count"`; BaselineNS int64 `json:"baseline_ns_per_round"`; CandidateNS int64 `json:"candidate_ns_per_round"`; SpeedupPercent float64 `json:"speedup_percent"`; Improvement float64 `json:"improvement_ratio"`; RadarDecision string `json:"zero_radar_decision"`; Measurement string `json:"measurement_scope"` }
type fixtureGraph map[int][]int
func makeFixtureGraph(nodes,degree int)fixtureGraph{g:=make(fixtureGraph,nodes);if nodes<1{return g};for n:=0;n<nodes;n++{for e:=1;e<=degree;e++{g[n]=append(g[n],(n+e*37+e*e+e)%nodes)}};return g}
func traversalReference(g fixtureGraph,start int)[]int{q:=[]int{start};seen:=[]int{start};out:=make([]int,0,len(g));for h:=0;h<len(q);h++{n:=q[h];out=append(out,n);for _,next:=range g[n]{found:=false;for _,old:=range seen{if old==next{found=true;break}};if !found{seen=append(seen,next);q=append(q,next)}}};return out}
func traversalIndexed(g fixtureGraph,start int)[]int{q:=[]int{start};seen:=map[int]struct{}{start:{}};out:=make([]int,0,len(g));for h:=0;h<len(q);h++{n:=q[h];out=append(out,n);for _,next:=range g[n]{if _,ok:=seen[next];ok{continue};seen[next]=struct{}{};q=append(q,next)}};return out}
func benchmarkOfflineVault(ctx context.Context,rounds int)(graphBenchmark,error){if rounds<5{rounds=5};const nodes=1800;const degree=4;g:=makeFixtureGraph(nodes,degree);base,cand:=[]time.Duration{},[]time.Duration{};for i:=0;i<2;i++{if !sameTraversal(traversalReference(g,0),traversalIndexed(g,0)){return graphBenchmark{},fmt.Errorf("warm-up replay mismatch")}};for i:=0;i<rounds;i++{select{case<-ctx.Done():return graphBenchmark{},ctx.Err();default:};runtime.GC();start:=time.Now();a:=traversalReference(g,0);base=append(base,time.Since(start));runtime.GC();start=time.Now();b:=traversalIndexed(g,0);cand=append(cand,time.Since(start));if !sameTraversal(a,b){return graphBenchmark{},fmt.Errorf("sandbox replay mismatch")}};bn,cn:=medianDuration(base).Nanoseconds(),medianDuration(cand).Nanoseconds();if bn<=0||cn<=0{return graphBenchmark{},fmt.Errorf("benchmark duration too small")};cmp,err:=radar.Compare(radar.Evidence{Name:"offline_vault_graph_traversal",Version:"v0.1.0",Benchmark:1e9/float64(bn),Source:"synthetic fixture",EvidenceID:"offline-vault-baseline"},radar.Evidence{Name:"offline_vault_graph_traversal",Version:"v0.2.0",Benchmark:1e9/float64(cn),Source:"synthetic fixture",EvidenceID:"offline-vault-candidate"});if err!=nil{return graphBenchmark{},err};return graphBenchmark{FixtureID:"offline-vault-graph-replay-v1",FixtureOnly:true,ReplayRounds:rounds,NodeCount:nodes,EdgeCount:nodes*degree,BaselineNS:bn,CandidateNS:cn,SpeedupPercent:(float64(bn)/float64(cn)-1)*100,Improvement:cmp.ImprovementRatio,RadarDecision:cmp.Recommendation,Measurement:"median of warmed repetitions; graph traversal phase only; not end-to-end invention time, real BOM cost, or production invention benchmark"},nil}
func sameTraversal(a,b []int)bool{if len(a)!=len(b){return false};for i:=range a{if a[i]!=b[i]{return false}};return true}
func medianDuration(v []time.Duration)time.Duration{c:=append([]time.Duration(nil),v...);sort.Slice(c,func(i,j int)bool{return c[i]<c[j]});return c[len(c)/2]}
func evaluateCatalog(ctx context.Context)([]CandidateEvaluation,graphBenchmark,error){bench,err:=benchmarkOfflineVault(ctx,5);if err!=nil{return nil,graphBenchmark{},err};protect,note:=rvx.Probe();if !protect{return nil,bench,fmt.Errorf("RVX artifact-protection probe failed: %s",note)};quotes:=[]struct{supplier string;parts,transport float64;stock bool}{{"fixture-kamukunji",1000,250,true},{"fixture-jumia",900,100,true}};best:=0.0;for _,q:=range quotes{if q.stock&&(best==0||q.parts+q.transport<best){best=q.parts+q.transport}};base:=quotes[0].parts+quotes[0].transport;bom:=(base-best)/base*100;sections:=[]string{"Prerequisites","Parts","Steps","Verification","Stop conditions"};shared:=sharedStrings([]string{"offline","identity","audit"},[]string{"offline","audit","agriculture","education"});dedup:=len(uniqueStrings([]string{"source-a","source-a","source-b","source-c","source-c"}));cached:=len(uniqueStrings([]string{"spec-1","spec-1","spec-1","spec-1","spec-1"}));lookup:=benchmarkPathLookup(ctx);if !lookup.Passed{return nil,bench,fmt.Errorf("path-index sandbox fixture failed")};chain,bounded:=auditChainProbe(),boundedInputProbe();evals:=[]CandidateEvaluation{
{ID:"graph-indexed",Category:"graph_traversal",ImprovementType:"measured_speed",BaselineValue:float64(bench.BaselineNS),CandidateValue:float64(bench.CandidateNS),ImprovementPct:bench.SpeedupPercent,Passed:bench.Improvement>1.30,MeasurementSource:"five runs of synthetic offline_vault graph fixture",Evidence:map[string]any{"baseline_ns_per_round":bench.BaselineNS,"candidate_ns_per_round":bench.CandidateNS,"ratio":bench.Improvement},Note:"Graph traversal phase only; not complete invention time."},
{ID:"bom-cost-ranked",Category:"bom_search",ImprovementType:"fixture_cost_reduction",BaselineValue:base,CandidateValue:best,ImprovementPct:bom,Passed:bom>0,MeasurementSource:"illustrative synthetic cost units, not KES/vendor prices",Evidence:map[string]any{"currency":"fixture_cost_units","prices_verified":false}},
{ID:"hardware-guide-structured",Category:"hardware_guide",ImprovementType:"safety_checklist_coverage",BaselineValue:20,CandidateValue:float64(len(sections))/5*100,ImprovementPct:80,Passed:true,MeasurementSource:"required-section checklist fixture",Evidence:map[string]any{"required_sections":sections}},
{ID:"rvx-aead-envelope",Category:"rvx_protection",ImprovementType:"artifact_protection_controls",BaselineValue:0,CandidateValue:40,ImprovementPct:40,Passed:protect,MeasurementSource:"AES-GCM round-trip and tamper-detection probe",Evidence:map[string]any{"probe":note,"security_score_is_rubric_not_cryptographic_strength":true}},
{ID:"cross-industry-pollination",Category:"pollination",ImprovementType:"cross_domain_reuse_count",BaselineValue:1,CandidateValue:float64(len(shared)),ImprovementPct:float64(len(shared)-1)*100,Passed:len(shared)>1,MeasurementSource:"synthetic capability-set fixture",Evidence:map[string]any{"shared_capabilities":shared,"no_automatic_integration":true}},
{ID:"evidence-hash-dedup",Category:"evidence",ImprovementType:"duplicate_evidence_reduction",BaselineValue:5,CandidateValue:float64(dedup),ImprovementPct:float64(5-dedup)/5*100,Passed:dedup==3,MeasurementSource:"five-row synthetic evidence fixture"},
{ID:"canonical-spec-cache",Category:"spec_cache",ImprovementType:"redundant_builds_avoided",BaselineValue:5,CandidateValue:float64(cached),ImprovementPct:float64(5-cached)/5*100,Passed:cached==1,MeasurementSource:"repeated immutable-spec fixture"},
{ID:"repository-path-index",Category:"path_index",ImprovementType:"measured_lookup_speed",BaselineValue:float64(lookup.BaselineNS),CandidateValue:float64(lookup.CandidateNS),ImprovementPct:lookup.ImprovementPct,Passed:lookup.ImprovementPct>0,MeasurementSource:"five runs of synthetic path-index fixture",Evidence:map[string]any{"lookup_fixture_size":20000}},
{ID:"tamper-evident-audit-chain",Category:"audit_integrity",ImprovementType:"tamper_detection",BaselineValue:0,CandidateValue:1,ImprovementPct:100,Passed:chain,MeasurementSource:"audit-chain integrity fixture",Evidence:map[string]any{"tamper_detection_passed":chain}},
{ID:"bounded-input-guard",Category:"input_safety",ImprovementType:"unsafe_input_rejection",BaselineValue:0,CandidateValue:1,ImprovementPct:100,Passed:bounded,MeasurementSource:"oversized and path-traversal input fixture",Evidence:map[string]any{"candidate_code_execution":false}},}
for i:=range evals{spec,ok:=sourceFor(evals[i].ID);if !ok{return nil,bench,fmt.Errorf("missing candidate template for %s",evals[i].ID)};if err:=validateCandidateSource(spec);err!=nil{evals[i].Passed=false;evals[i].Note=err.Error()}};return evals,bench,nil}
type lookupBenchmark struct{BaselineNS int64;CandidateNS int64;ImprovementPct float64;Passed bool}
func benchmarkPathLookup(ctx context.Context)lookupBenchmark{const count=20000;paths:=make([]string,count);index:=make(map[string]int,count);for i:=range paths{paths[i]=fmt.Sprintf("repo/module/file-%05d.go",i);index[paths[i]]=i};target:=paths[len(paths)-1];const rounds=5;var base,candidate time.Duration;for i:=0;i<rounds;i++{select{case<-ctx.Done():return lookupBenchmark{};default:};start:=time.Now();found:=-1;for n,p:=range paths{if p==target{found=n;break}};base+=time.Since(start);if found!=count-1{return lookupBenchmark{}};start=time.Now();found=index[target];candidate+=time.Since(start);if found!=count-1{return lookupBenchmark{}}};b,c:=base.Nanoseconds()/rounds,candidate.Nanoseconds()/rounds;if b<=0||c<=0{return lookupBenchmark{}};return lookupBenchmark{BaselineNS:b,CandidateNS:c,ImprovementPct:(float64(b)/float64(c)-1)*100,Passed:true}}
func sharedStrings(a,b []string)[]string{set:=map[string]bool{};for _,v:=range a{set[v]=true};out:=[]string{};seen:=map[string]bool{};for _,v:=range b{if set[v]&&!seen[v]{seen[v]=true;out=append(out,v)}};sort.Strings(out);return out}
func uniqueStrings(values []string)[]string{seen:=map[string]bool{};out:=[]string{};for _,v:=range values{v=strings.TrimSpace(v);if v!=""&&!seen[v]{seen[v]=true;out=append(out,v)}};return out}
func auditChainProbe()bool{events:=[]string{"proposed","tested","await_merge"};hashes:=[]string{};prev:="";for _,entry:=range events{prev=hashString(prev+"\n"+entry);hashes=append(hashes,prev)};return verifyHashChain(events,hashes)&&!verifyHashChain([]string{"proposed","tampered","await_merge"},hashes)}
func boundedInputProbe()bool{return validBoundedInput("offline_vault")&&!validBoundedInput("../outside")&&!validBoundedInput(strings.Repeat("x",4097))}
func verifyHashChain(events,hashes []string)bool{if len(events)!=len(hashes){return false};previous:="";for i,event:=range events{previous=hashString(previous+"\n"+event);if hashes[i]!=previous{return false}};return true}
func validBoundedInput(value string)bool{if value==""||len(value)>4096||strings.ContainsRune(value,0){return false};clean:=strings.ReplaceAll(value,"\\","/");if strings.HasPrefix(clean,"/")||(len(clean)>=2&&clean[1]==':'){return false};for _,part:=range strings.Split(clean,"/"){if part==".."{return false}};return true}
